function compareByteOrder(left, right) {
  const s1 = normalizedString(left);
  const s2 = normalizedString(right);
  if (s1 < s2) return -1;
  if (s1 > s2) return 1;
  return 0;
}

function compareRows(left, right) {
  return compareByteOrder(left.question_key, right.question_key);
}
```

